import { DESKTOP_COLS_NUMBER, MOBILE_COLS_NUMBER, TABLET_COLS_NUMBER } from "./constants";
export const adaptGridState = (gridState) => {
    const { lg, md, sm, lgStart, mdStart, smStart } = gridState;
    // Example:
    // 9 + 4 == 13 -> | 9 | 10 | 11 | 12 | -> the last column is 12 == 12 => OK
    // 9 + 5 == 14 -> | 9 | 10 | 11 | 12 | 13 | -> the last column is 13 > 12 => should be adapted to 12
    if (lg && lgStart && (lg + lgStart - 1) > DESKTOP_COLS_NUMBER) {
        gridState.lg = DESKTOP_COLS_NUMBER - lgStart + 1;
    }
    if (md && mdStart && (md + mdStart - 1) > TABLET_COLS_NUMBER) {
        gridState.md = TABLET_COLS_NUMBER - mdStart + 1;
    }
    if (sm && smStart && (sm + smStart - 1) > MOBILE_COLS_NUMBER) {
        gridState.sm = MOBILE_COLS_NUMBER - smStart + 1;
    }
};
